BEGIN;
SELECT plan(18);
INSERT INTO auth.users(id,email) VALUES('e2300000-0000-4000-8000-000000000001','w4-staff-admin@example.invalid');
INSERT INTO public.profiles(id,email,full_name,role,account_state) VALUES('e2300000-0000-4000-8000-000000000001','w4-staff-admin@example.invalid','Staff fixture','admin','active');
INSERT INTO public.courses(id,slug,title,subtitle,category,summary,description,venue,status,published_at,provenance)
VALUES('e2300000-0000-4000-8000-000000000002','w4-staff-test','Staff fixture','Course test subtitle','Training','Fixture summary','Fixture description for staff enrollment','Dhaka','published',now(),'{"class":"B","verified":false,"source":"pgTAP fixture"}');
INSERT INTO public.batches(id,course_id,slug,batch_number,name,start_date,end_date,schedule_description,capacity,fee_poisha,status,venue,accept_applications,provenance)
VALUES
 ('e2300000-0000-4000-8000-000000000003','e2300000-0000-4000-8000-000000000002','w4-staff-paid',1,'Paid batch',current_date+1,current_date+2,'Weekend sessions',6,750000,'upcoming','Dhaka',false,'{"class":"B","verified":false,"source":"pgTAP fixture"}'),
 ('e2300000-0000-4000-8000-000000000004','e2300000-0000-4000-8000-000000000002','w4-staff-free',2,'Free batch',current_date+1,current_date+2,'Weekend sessions',NULL,0,'upcoming','Dhaka',false,'{"class":"B","verified":false,"source":"pgTAP fixture"}');
SELECT ok(NOT has_function_privilege('anon','public.create_confirmed_staff_admission(uuid,uuid,timestamptz,text,text,text,text,jsonb,jsonb,text,text,bigint,bigint,text,text,boolean,boolean,boolean)','EXECUTE') AND NOT has_function_privilege('authenticated','public.create_confirmed_staff_admission(uuid,uuid,timestamptz,text,text,text,text,jsonb,jsonb,text,text,bigint,bigint,text,text,boolean,boolean,boolean)','EXECUTE'),'Browser cannot confirm manual admission');
SET LOCAL ROLE service_role;
SELECT is((SELECT public.create_confirmed_staff_admission('e2300000-0000-4000-8000-000000000001',id,updated_at,'LNA-W4S0-0001','Cash Fixture','cash-fixture@example.invalid','01799002301','{}','[]','cash','cash',700000,0,'C',NULL,false,true,false)->>'ok' FROM public.batches WHERE slug='w4-staff-paid'),'true','Active Admin records cash while public intake is Off');
SELECT ok((SELECT status='confirmed' AND payment_method='cash' AND payment_status='verified' AND payable_poisha=700000 AND staff_payment_details->>'original_payable_poisha'='750000' FROM public.enrollments WHERE public_ref='LNA-W4S0-0001'),'Cash and original fee persisted');
SELECT is((SELECT public.create_confirmed_staff_admission('e2300000-0000-4000-8000-000000000001',id,updated_at,'LNA-W4S0-0002','Duplicate Fixture','duplicate-cash@example.invalid','01799002302','{}','[]','cash','cash',700000,0,'C',NULL,false,true,false)->>'code' FROM public.batches WHERE slug='w4-staff-paid'),'REFERENCE_ACK_REQUIRED','Repeated cash receipt requires acknowledgement');
SELECT is((SELECT public.create_confirmed_staff_admission('e2300000-0000-4000-8000-000000000001',id,updated_at,'LNA-W4S0-0002','Duplicate Fixture','duplicate-cash@example.invalid','01799002302','{}','[]','cash','cash',700000,0,'C',NULL,true,true,false)->>'ok' FROM public.batches WHERE slug='w4-staff-paid'),'true','Acknowledged cash receipt creates separate collection');
SELECT is((SELECT public.create_confirmed_staff_admission('e2300000-0000-4000-8000-000000000001',id,updated_at,'LNA-W4S0-0003','Waiver Fixture','waiver-fixture@example.invalid','01799002303','{}','[]','full_fee_waiver',NULL,750000,750000,'W','Approved',false,true,false)->>'ok' FROM public.batches WHERE slug='w4-staff-paid'),'true','Full waiver confirms without payment');
SELECT ok((SELECT payment_method='full_fee_waiver' AND payment_status='not_required' AND payable_poisha=0 AND discount_amount_poisha=750000 AND staff_payment_details->>'waiver_reason'='Approved' FROM public.enrollments WHERE public_ref='LNA-W4S0-0003'),'Full waiver is distinct from genuinely free registration');
SELECT is((SELECT public.create_confirmed_staff_admission('e2300000-0000-4000-8000-000000000001',id,updated_at,'LNA-W4S0-0004','Partial Fixture','partial-fixture@example.invalid','01799002304','{}','[]','partial_fee_waiver','bank_transfer',750000,250000,'B','Approved',false,true,false)->>'ok' FROM public.batches WHERE slug='w4-staff-paid'),'true','Partial waiver with bank collection confirmed');
SELECT ok((SELECT payment_method='bank_transfer' AND payable_poisha=500000 AND staff_payment_details->>'waiver_poisha'='250000' FROM public.enrollments WHERE public_ref='LNA-W4S0-0004'),'Partial waiver retains collected amount and waiver separately');
SELECT is((SELECT public.create_confirmed_staff_admission('e2300000-0000-4000-8000-000000000001',id,updated_at,'LNA-W4S0-0005','Invalid Fixture','invalid-fixture@example.invalid','01799002305','{}','[]','partial_fee_waiver','cash',750000,750000,'X','Approved',false,true,false)->>'code' FROM public.batches WHERE slug='w4-staff-paid'),'INVALID_PAYMENT','Partial waiver cannot reduce amount to zero');
SELECT is((SELECT public.create_confirmed_staff_admission('e2300000-0000-4000-8000-000000000001',id,updated_at,'LNA-W4S0-0005','bKash Fixture','bkash-fixture@example.invalid','01799002305','{}','[]','bkash','bkash',750000,0,'BK23',NULL,false,true,false)->>'ok' FROM public.batches WHERE slug='w4-staff-paid'),'true','Recorded bKash collection confirms');
SELECT is((SELECT public.create_confirmed_staff_admission('e2300000-0000-4000-8000-000000000001',id,updated_at,'LNA-W4S0-0006','Duplicate bKash','duplicate-bkash@example.invalid','01799002306','{}','[]','bkash','bkash',750000,0,'BK23',NULL,true,true,false)->>'code' FROM public.batches WHERE slug='w4-staff-paid'),'DUPLICATE_PAYMENT_REFERENCE','Known bKash cannot be reused even with acknowledgement');
SELECT is((SELECT public.create_confirmed_staff_admission('e2300000-0000-4000-8000-000000000001',id,updated_at,'LNA-W4S0-0006','Duplicate Phone','duplicate-phone@example.invalid','01799002305','{}','[]','cash','cash',750000,0,'Y',NULL,false,true,false)->>'code' FROM public.batches WHERE slug='w4-staff-paid'),'DUPLICATE_ENROLLMENT','Same phone cannot confirm another seat in the batch');
SELECT is((SELECT public.create_confirmed_staff_admission('e2300000-0000-4000-8000-000000000001',id,updated_at,'LNA-W4S0-0006','Bank Fixture','bank-fixture@example.invalid','01799002306','{}','[]','bank_transfer','bank_transfer',750000,0,'B',NULL,true,true,false)->>'ok' FROM public.batches WHERE slug='w4-staff-paid'),'true','Acknowledged repeat bank reference is permitted');
SELECT is((SELECT public.create_confirmed_staff_admission('e2300000-0000-4000-8000-000000000001',id,updated_at,'LNA-W4S0-0007','Capacity Fixture','capacity-fixture@example.invalid','01799002307','{}','[]','cash','cash',750000,0,'Z',NULL,false,true,false)->>'code' FROM public.batches WHERE slug='w4-staff-paid'),'BATCH_FULL','Confirmed staff admissions count against fixed capacity');
SELECT is((SELECT public.create_confirmed_staff_admission('e2300000-0000-4000-8000-000000000001',id,updated_at,'LNA-W4S0-0008','Cash Fixture','cash-fixture@example.invalid','01799002301','{}','[]','free',NULL,0,0,NULL,NULL,false,false,true)->>'ok' FROM public.batches WHERE slug='w4-staff-free'),'true','Exact existing student can join another free batch');
SELECT is((SELECT count(DISTINCT l.student_id) FROM public.student_enrollment_links l JOIN public.enrollments e ON e.id=l.enrollment_id WHERE e.public_ref IN ('LNA-W4S0-0001','LNA-W4S0-0008')),1::bigint,'Multiple confirmed admissions link to the same student');
SELECT ok((SELECT count(*)=7 FROM public.audit_events WHERE action='staff_confirmed_admission' AND actor_id='e2300000-0000-4000-8000-000000000001') AND NOT EXISTS(SELECT 1 FROM public.payment_attempts pa JOIN public.enrollments e ON e.id=pa.enrollment_id WHERE e.course_id='e2300000-0000-4000-8000-000000000002'),'Every confirmation audited without invented gateway payments');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
